{
  "name": "SolarChain Twin",
  "description": "A decision-grade Digital Twin for the Solar Industry Supply Chain. Features real-time node monitoring, scenario simulation, and multi-objective optimization analysis powered by Gemini."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum NodeType {
  RAW_MATERIAL = 'RAW_MATERIAL',
  MANUFACTURING = 'MANUFACTURING',
  LOGISTICS = 'LOGISTICS',
  DISTRIBUTION = 'DISTRIBUTION',
  INSTALLATION = 'INSTALLATION'
}

export enum NodeStatus {
  OPTIMAL = 'OPTIMAL',
  WARNING = 'WARNING',
  CRITICAL = 'CRITICAL',
  OFFLINE = 'OFFLINE'
}

export interface SupplyNode {
  id: string;
  name: string;
  type: NodeType;
  status: NodeStatus;
  location: string;
  inventoryLevel: number; // 0-100%
  capacityUtilization: number; // 0-100%
  leadTimeDays: number;
  coordinates: { x: number; y: number };
}

export interface SimulationParams {
  polysiliconPriceChange: number; // Percentage
  logisticDisruption: boolean;
  demandSurge: number; // Percentage
  tariffImposition: boolean;
  weatherEvent: boolean;
}

export interface SimulationResult {
  narrative: string;
  kpiImpact: {
    landedCostChange: number;
    otifChange: number;
    carbonFootprintChange: number;
    inventoryRisk: 'Low' | 'Medium' | 'High';
  };
  recommendations: string[];
}

export interface KPI {
  label: string;
  value: string;
  unit: string;
  trend: number; // percentage change
  status: 'positive' | 'negative' | 'neutral';
}

import { GoogleGenAI, Type } from "@google/genai";
import { SimulationParams, SimulationResult } from "../types";

const processApiKey = process.env.API_KEY || '';

// Mock result for fallback if no API key is present or error occurs
const MOCK_RESULT: SimulationResult = {
  narrative: "Simulation completed using fallback logic. A spike in polysilicon prices has cascaded through the wafer production capability in Southeast Asia. Expect margin compression of 12% unless buffer stock is utilized immediately.",
  kpiImpact: {
    landedCostChange: 15.4,
    otifChange: -8.2,
    carbonFootprintChange: 2.1,
    inventoryRisk: 'High'
  },
  recommendations: [
    "Activate alternative supplier agreements in region B.",
    "Shift modal transport from Sea to Rail for urgent batches.",
    "Defer Tier 3 customer orders to preserve key account service levels."
  ]
};

export const runSimulationAnalysis = async (params: SimulationParams): Promise<SimulationResult> => {
  if (!processApiKey) {
    console.warn("No API Key found. Returning mock simulation data.");
    return new Promise(resolve => setTimeout(() => resolve(MOCK_RESULT), 1500));
  }

  try {
    const ai = new GoogleGenAI({ apiKey: processApiKey });

    const prompt = `
      Act as a Digital Twin Simulation Engine for the Solar Supply Chain.
      Analyze the impact of the following variables:
      - Polysilicon Price Change: ${params.polysiliconPriceChange}%
      - Logistics Disruption (Port/Route): ${params.logisticDisruption ? 'YES (Major delays)' : 'NO'}
      - Demand Surge: ${params.demandSurge}%
      - New Tariffs: ${params.tariffImposition ? 'YES' : 'NO'}
      - Extreme Weather Event: ${params.weatherEvent ? 'YES' : 'NO'}

      Provide a structured JSON output containing:
      1. A short narrative describing the propagation of these shocks through the nodes (Raw Materials -> Manufacturing -> Logistics -> Installation).
      2. Quantitative impact estimates on KPIs (Landed Cost, OTIF, Carbon).
      3. Strategic recommendations for mitigation.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-latest',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            narrative: { type: Type.STRING },
            kpiImpact: {
              type: Type.OBJECT,
              properties: {
                landedCostChange: { type: Type.NUMBER, description: "Percentage change in landed cost" },
                otifChange: { type: Type.NUMBER, description: "Percentage point change in On-Time-In-Full" },
                carbonFootprintChange: { type: Type.NUMBER, description: "Percentage change in emissions" },
                inventoryRisk: { type: Type.STRING, enum: ["Low", "Medium", "High"] }
              }
            },
            recommendations: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as SimulationResult;
    }

    throw new Error("Empty response from AI");

  } catch (error) {
    console.error("Simulation failed:", error);
    return MOCK_RESULT;
  }
};

import React, { useMemo } from 'react';
import { SupplyNode, NodeType, NodeStatus } from '../types';

interface NetworkMapProps {
  nodes: SupplyNode[];
  onNodeSelect: (node: SupplyNode) => void;
  selectedNodeId: string | null;
}

const NetworkMap: React.FC<NetworkMapProps> = ({ nodes, onNodeSelect, selectedNodeId }) => {
  // Simple connections logic: Connect Raw -> Mfg -> Logistics -> Dist -> Install
  // In a real app, this would be a graph data structure.
  const connections = useMemo(() => {
    const lines: JSX.Element[] = [];

    // Helper to draw line between node types
    const connectTypes = (fromType: NodeType, toType: NodeType) => {
      const sources = nodes.filter(n => n.type === fromType);
      const targets = nodes.filter(n => n.type === toType);

      sources.forEach(src => {
        targets.forEach(tgt => {
          // Draw a connection if they are somewhat "connected" in our mock logic
          // For visual simplicity, we connect all sources of one tier to all targets of next tier
          // but visually thin them out
          const key = `${src.id}-${tgt.id}`;
          lines.push(
            <line
              key={key}
              x1={src.coordinates.x}
              y1={src.coordinates.y}
              x2={tgt.coordinates.x}
              y2={tgt.coordinates.y}
              stroke="#334155"
              strokeWidth="1"
              opacity="0.4"
              className="transition-all duration-500"
            />
          );
        });
      });
    };

    connectTypes(NodeType.RAW_MATERIAL, NodeType.MANUFACTURING);
    connectTypes(NodeType.MANUFACTURING, NodeType.LOGISTICS);
    connectTypes(NodeType.LOGISTICS, NodeType.DISTRIBUTION);
    connectTypes(NodeType.DISTRIBUTION, NodeType.INSTALLATION);

    return lines;
  }, [nodes]);

  const getNodeColor = (status: NodeStatus) => {
    switch (status) {
      case NodeStatus.OPTIMAL: return '#10b981'; // Emerald 500
      case NodeStatus.WARNING: return '#f59e0b'; // Amber 500
      case NodeStatus.CRITICAL: return '#ef4444'; // Red 500
      case NodeStatus.OFFLINE: return '#64748b'; // Slate 500
      default: return '#cbd5e1';
    }
  };

  return (
    <div className="relative w-full h-[600px] bg-slate-900 rounded-xl border border-slate-700 overflow-hidden shadow-2xl">
      <div className="absolute top-4 left-4 z-10 bg-slate-800/80 backdrop-blur p-2 rounded text-xs text-slate-300 border border-slate-600">
        <h3 className="font-bold text-white mb-1">Global Supply Chain Network</h3>
        <p>Real-time node telemetry</p>
      </div>

      <svg className="w-full h-full" viewBox="0 0 1000 600">
        <defs>
          <radialGradient id="nodeGlow" cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
            <stop offset="0%" stopColor="white" stopOpacity="0.8" />
            <stop offset="100%" stopColor="white" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Connections Layer */}
        <g>{connections}</g>

        {/* Nodes Layer */}
        {nodes.map(node => (
          <g 
            key={node.id} 
            onClick={() => onNodeSelect(node)}
            className="cursor-pointer transition-all duration-300 hover:opacity-80"
          >
            {selectedNodeId === node.id && (
              <circle
                cx={node.coordinates.x}
                cy={node.coordinates.y}
                r={20}
                fill="none"
                stroke={getNodeColor(node.status)}
                strokeWidth="2"
                strokeDasharray="4 2"
                className="animate-spin-slow" // Assume custom tailwind config or standard spin
              />
            )}

            {/* Ping animation for active nodes */}
            {node.status !== NodeStatus.OFFLINE && (
               <circle
               cx={node.coordinates.x}
               cy={node.coordinates.y}
               r={8}
               fill={getNodeColor(node.status)}
               opacity="0.3"
             >
               <animate attributeName="r" from="8" to="16" dur="2s" repeatCount="indefinite" />
               <animate attributeName="opacity" from="0.3" to="0" dur="2s" repeatCount="indefinite" />
             </circle>
            )}

            <circle
              cx={node.coordinates.x}
              cy={node.coordinates.y}
              r={6}
              fill={getNodeColor(node.status)}
              stroke="#0f172a"
              strokeWidth="2"
            />

            <text
              x={node.coordinates.x}
              y={node.coordinates.y + 16}
              textAnchor="middle"
              fill="#94a3b8"
              fontSize="10"
              fontWeight={selectedNodeId === node.id ? "bold" : "normal"}
              className="pointer-events-none select-none"
            >
              {node.name}
            </text>
          </g>
        ))}
      </svg>

      {/* Legend */}
      <div className="absolute bottom-4 right-4 flex gap-4 text-xs text-slate-400 bg-slate-800/90 p-2 rounded border border-slate-700">
        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-emerald-500"></div> Optimal</div>
        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-amber-500"></div> Warning</div>
        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-red-500"></div> Critical</div>
      </div>
    </div>
  );
};

export default NetworkMap;

import React from 'react';
import { KPI } from '../types';

interface KPICardProps {
  kpi: KPI;
}

const KPICard: React.FC<KPICardProps> = ({ kpi }) => {
  const isPositive = kpi.status === 'positive';
  const isNegative = kpi.status === 'negative';

  // For cost/emissions, "positive" status usually means the metric went DOWN (good), but trend display should handle sign.
  // We'll rely on the `status` prop to color it.

  return (
    <div className="bg-slate-800 rounded-lg p-5 border border-slate-700 hover:border-slate-600 transition-colors">
      <div className="text-slate-400 text-sm font-medium uppercase tracking-wider mb-1">
        {kpi.label}
      </div>
      <div className="flex items-baseline justify-between">
        <div className="text-2xl font-bold text-slate-100">
          {kpi.value} <span className="text-sm font-normal text-slate-400">{kpi.unit}</span>
        </div>
        <div className={`text-sm font-medium ${isPositive ? 'text-emerald-400' : isNegative ? 'text-red-400' : 'text-slate-400'}`}>
          {kpi.trend > 0 ? '+' : ''}{kpi.trend}%
        </div>
      </div>
    </div>
  );
};

export default KPICard;

