import React, { useState } from 'react';
import { SimulationParams } from '../types';

interface SimulationPanelProps {
  onRunSimulation: (params: SimulationParams) => void;
  isSimulating: boolean;
}

const SimulationPanel: React.FC<SimulationPanelProps> = ({ onRunSimulation, isSimulating }) => {
  const [params, setParams] = useState<SimulationParams>({
    polysiliconPriceChange: 0,
    logisticDisruption: false,
    demandSurge: 0,
    tariffImposition: false,
    weatherEvent: false,
  });

  const handleChange = (field: keyof SimulationParams, value: any) => {
    setParams(prev => ({ ...prev, [field]: value }));
  };

  return (
    <div className="bg-slate-800 rounded-xl border border-slate-700 p-6 flex flex-col h-full">
      <div className="mb-6">
        <h2 className="text-xl font-bold text-white flex items-center gap-2">
          <svg className="w-6 h-6 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.384-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
          </svg>
          Scenario Builder
        </h2>
        <p className="text-slate-400 text-sm mt-1">Adjust parameters to stress-test the supply chain.</p>
      </div>

      <div className="space-y-6 flex-grow">
        {/* Poly Price Slider */}
        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">
            Polysilicon Price Shock ({params.polysiliconPriceChange > 0 ? '+' : ''}{params.polysiliconPriceChange}%)
          </label>
          <input
            type="range"
            min="-50"
            max="100"
            step="5"
            value={params.polysiliconPriceChange}
            onChange={(e) => handleChange('polysiliconPriceChange', parseInt(e.target.value))}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
          <div className="flex justify-between text-xs text-slate-500 mt-1">
            <span>-50%</span>
            <span>0%</span>
            <span>+100%</span>
          </div>
        </div>

        {/* Demand Surge Slider */}
        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">
            Demand Surge ({params.demandSurge}%)
          </label>
          <input
            type="range"
            min="0"
            max="200"
            step="10"
            value={params.demandSurge}
            onChange={(e) => handleChange('demandSurge', parseInt(e.target.value))}
            className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-blue-500"
          />
          <div className="flex justify-between text-xs text-slate-500 mt-1">
            <span>BAU</span>
            <span>+200%</span>
          </div>
        </div>

        {/* Toggles */}
        <div className="space-y-4 pt-4 border-t border-slate-700">
          <label className="flex items-center justify-between cursor-pointer group">
            <span className="text-sm font-medium text-slate-300 group-hover:text-white transition">Logistics Disruption (Port Closure)</span>
            <input 
              type="checkbox" 
              checked={params.logisticDisruption}
              onChange={(e) => handleChange('logisticDisruption', e.target.checked)}
              className="w-5 h-5 rounded border-slate-600 bg-slate-700 text-blue-600 focus:ring-blue-500 focus:ring-offset-slate-800"
            />
          </label>

          <label className="flex items-center justify-between cursor-pointer group">
            <span className="text-sm font-medium text-slate-300 group-hover:text-white transition">New Tariff Enforcement</span>
            <input 
              type="checkbox" 
              checked={params.tariffImposition}
              onChange={(e) => handleChange('tariffImposition', e.target.checked)}
              className="w-5 h-5 rounded border-slate-600 bg-slate-700 text-blue-600 focus:ring-blue-500 focus:ring-offset-slate-800"
            />
          </label>

          <label className="flex items-center justify-between cursor-pointer group">
            <span className="text-sm font-medium text-slate-300 group-hover:text-white transition">Extreme Weather Event</span>
            <input 
              type="checkbox" 
              checked={params.weatherEvent}
              onChange={(e) => handleChange('weatherEvent', e.target.checked)}
              className="w-5 h-5 rounded border-slate-600 bg-slate-700 text-blue-600 focus:ring-blue-500 focus:ring-offset-slate-800"
            />
          </label>
        </div>
      </div>

      <div className="mt-8">
        <button
          onClick={() => onRunSimulation(params)}
          disabled={isSimulating}
          className={`w-full py-3 px-4 rounded-lg font-bold text-white shadow-lg transition-all
            ${isSimulating 
              ? 'bg-slate-600 cursor-not-allowed opacity-75' 
              : 'bg-blue-600 hover:bg-blue-500 active:transform active:scale-95 shadow-blue-900/20'
