                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              Running Model...
            </span>
          ) : (
            "Run Monte Carlo Simulation"
          )}
        </button>
      </div>
    </div>
  );
};

export default SimulationPanel;

import React, { useState, useEffect } from 'react';
import NetworkMap from './components/NetworkMap';
import KPICard from './components/KPICard';
import SimulationPanel from './components/SimulationPanel';
import { CostTrendChart, InventoryChart } from './components/Charts';
import { runSimulationAnalysis } from './services/geminiService';
import { SupplyNode, NodeType, NodeStatus, KPI, SimulationParams, SimulationResult } from './types';

// Mock Initial Data
const INITIAL_NODES: SupplyNode[] = [
  { id: '1', name: 'Xinjiang Silicon Co.', type: NodeType.RAW_MATERIAL, status: NodeStatus.OPTIMAL, location: 'China', inventoryLevel: 80, capacityUtilization: 92, leadTimeDays: 5, coordinates: { x: 100, y: 150 } },
  { id: '2', name: 'Wacker Chemie', type: NodeType.RAW_MATERIAL, status: NodeStatus.OPTIMAL, location: 'Germany', inventoryLevel: 70, capacityUtilization: 85, leadTimeDays: 7, coordinates: { x: 100, y: 450 } },
  { id: '3', name: 'Wafer Fab Alpha', type: NodeType.MANUFACTURING, status: NodeStatus.WARNING, location: 'Vietnam', inventoryLevel: 45, capacityUtilization: 98, leadTimeDays: 14, coordinates: { x: 300, y: 300 } },
  { id: '4', name: 'Module Assembly Z', type: NodeType.MANUFACTURING, status: NodeStatus.OPTIMAL, location: 'Malaysia', inventoryLevel: 60, capacityUtilization: 88, leadTimeDays: 10, coordinates: { x: 500, y: 300 } },
  { id: '5', name: 'Port of Shanghai', type: NodeType.LOGISTICS, status: NodeStatus.OPTIMAL, location: 'China', inventoryLevel: 0, capacityUtilization: 75, leadTimeDays: 20, coordinates: { x: 650, y: 200 } },
  { id: '6', name: 'Rotterdam Hub', type: NodeType.LOGISTICS, status: NodeStatus.OPTIMAL, location: 'Netherlands', inventoryLevel: 50, capacityUtilization: 60, leadTimeDays: 5, coordinates: { x: 650, y: 450 } },
  { id: '7', name: 'Euro Distribution', type: NodeType.DISTRIBUTION, status: NodeStatus.OPTIMAL, location: 'Germany', inventoryLevel: 30, capacityUtilization: 80, leadTimeDays: 2, coordinates: { x: 800, y: 380 } },
  { id: '8', name: 'Solar Farm Project X', type: NodeType.INSTALLATION, status: NodeStatus.WARNING, location: 'Spain', inventoryLevel: 10, capacityUtilization: 100, leadTimeDays: 0, coordinates: { x: 900, y: 300 } },
];

const INITIAL_KPIS: KPI[] = [
  { label: 'OTIF Rate', value: '94.2', unit: '%', trend: -1.2, status: 'negative' },
  { label: 'Landed Cost', value: '0.22', unit: '$/W', trend: 3.5, status: 'negative' },
  { label: 'Avg Lead Time', value: '42', unit: 'days', trend: 0, status: 'neutral' },
  { label: 'Scope 3 Carbon', value: '380', unit: 'kgCO2e/kW', trend: -5.0, status: 'positive' },
];

function App() {
  const [nodes, setNodes] = useState<SupplyNode[]>(INITIAL_NODES);
  const [selectedNode, setSelectedNode] = useState<SupplyNode | null>(null);
  const [kpis, setKpis] = useState<KPI[]>(INITIAL_KPIS);
  const [isSimulating, setIsSimulating] = useState(false);
  const [simulationResult, setSimulationResult] = useState<SimulationResult | null>(null);

  const handleRunSimulation = async (params: SimulationParams) => {
    setIsSimulating(true);
    setSimulationResult(null);

    // Visual effect: Set nodes to random status to simulate "Processing" or "Impact"
    const tempNodes = nodes.map(n => ({
        ...n,
        status: Math.random() > 0.7 ? NodeStatus.WARNING : NodeStatus.OPTIMAL
    }));
    setNodes(tempNodes);

    try {
      const result = await runSimulationAnalysis(params);
      setSimulationResult(result);

      // Update KPIs based on simulation result
      const newKpis = [...kpis];
      newKpis[0] = { ...newKpis[0], trend: result.kpiImpact.otifChange, status: result.kpiImpact.otifChange >= 0 ? 'positive' : 'negative' };
      newKpis[1] = { ...newKpis[1], trend: result.kpiImpact.landedCostChange, status: result.kpiImpact.landedCostChange <= 0 ? 'positive' : 'negative' };
      newKpis[3] = { ...newKpis[3], trend: result.kpiImpact.carbonFootprintChange, status: result.kpiImpact.carbonFootprintChange <= 0 ? 'positive' : 'negative' };
      setKpis(newKpis);

      // Reset specific node statuses based on narrative hints (simple logic for demo)
      const severity = result.kpiImpact.inventoryRisk;
      const finalNodes = nodes.map(n => {
        if (severity === 'High' && (n.type === NodeType.MANUFACTURING || n.type === NodeType.LOGISTICS)) {
            return { ...n, status: NodeStatus.CRITICAL };
        }
        if (severity === 'Medium' && n.type === NodeType.LOGISTICS) {
            return { ...n, status: NodeStatus.WARNING };
        }
        return { ...n, status: NodeStatus.OPTIMAL };
      });
      setNodes(finalNodes);

    } catch (e) {
      console.error(e);
    } finally {
      setIsSimulating(false);
    }
  };

