import React, { useMemo } from 'react';
import { SupplyNode, NodeType, NodeStatus } from '../types';

interface NetworkMapProps {
  nodes: SupplyNode[];
  onNodeSelect: (node: SupplyNode) => void;
  selectedNodeId: string | null;
}

const NetworkMap: React.FC<NetworkMapProps> = ({ nodes, onNodeSelect, selectedNodeId }) => {
  // Simple connections logic: Connect Raw -> Mfg -> Logistics -> Dist -> Install
  // In a real app, this would be a graph data structure.
  const connections = useMemo(() => {
    const lines: React.ReactElement[] = [];

    // Helper to draw line between node types
    const connectTypes = (fromType: NodeType, toType: NodeType) => {
      const sources = nodes.filter(n => n.type === fromType);
      const targets = nodes.filter(n => n.type === toType);

      sources.forEach(src => {
        targets.forEach(tgt => {
          // Draw a connection if they are somewhat "connected" in our mock logic
          // For visual simplicity, we connect all sources of one tier to all targets of next tier
          // but visually thin them out
          const key = `${src.id}-${tgt.id}`;
          lines.push(
            <line
              key={key}
              x1={src.coordinates.x}
              y1={src.coordinates.y}
              x2={tgt.coordinates.x}
              y2={tgt.coordinates.y}
              stroke="#334155"
              strokeWidth="1"
              opacity="0.4"
              className="transition-all duration-500"
            />
          );
        });
      });
    };

    connectTypes(NodeType.RAW_MATERIAL, NodeType.MANUFACTURING);
    connectTypes(NodeType.MANUFACTURING, NodeType.LOGISTICS);
    connectTypes(NodeType.LOGISTICS, NodeType.DISTRIBUTION);
    connectTypes(NodeType.DISTRIBUTION, NodeType.INSTALLATION);

    return lines;
  }, [nodes]);

  const getNodeColor = (status: NodeStatus) => {
    switch (status) {
      case NodeStatus.OPTIMAL: return '#10b981'; // Emerald 500
      case NodeStatus.WARNING: return '#f59e0b'; // Amber 500
      case NodeStatus.CRITICAL: return '#ef4444'; // Red 500
      case NodeStatus.OFFLINE: return '#64748b'; // Slate 500
      default: return '#cbd5e1';
    }
  };

  return (
    <div className="relative w-full h-[600px] bg-slate-900 rounded-xl border border-slate-700 overflow-hidden shadow-2xl">
      <div className="absolute top-4 left-4 z-10 bg-slate-800/80 backdrop-blur p-2 rounded text-xs text-slate-300 border border-slate-600">
        <h3 className="font-bold text-white mb-1">Global Supply Chain Network</h3>
        <p>Real-time node telemetry</p>
      </div>

      <svg className="w-full h-full" viewBox="0 0 1000 600">
        <defs>
          <radialGradient id="nodeGlow" cx="50%" cy="50%" r="50%" fx="50%" fy="50%">
            <stop offset="0%" stopColor="white" stopOpacity="0.8" />
            <stop offset="100%" stopColor="white" stopOpacity="0" />
          </radialGradient>
        </defs>

        {/* Connections Layer */}
        <g>{connections}</g>

        {/* Nodes Layer */}
        {nodes.map(node => (
          <g 
            key={node.id} 
            onClick={() => onNodeSelect(node)}
            className="cursor-pointer transition-all duration-300 hover:opacity-80"
          >
            {selectedNodeId === node.id && (
              <circle
                cx={node.coordinates.x}
                cy={node.coordinates.y}
                r={20}
                fill="none"
                stroke={getNodeColor(node.status)}
                strokeWidth="2"
                strokeDasharray="4 2"
                className="animate-spin-slow" // Assume custom tailwind config or standard spin
              />
            )}

            {/* Ping animation for active nodes */}
            {node.status !== NodeStatus.OFFLINE && (
               <circle
               cx={node.coordinates.x}
               cy={node.coordinates.y}
               r={8}
               fill={getNodeColor(node.status)}
               opacity="0.3"
             >
               <animate attributeName="r" from="8" to="16" dur="2s" repeatCount="indefinite" />
               <animate attributeName="opacity" from="0.3" to="0" dur="2s" repeatCount="indefinite" />
             </circle>
            )}

            <circle
              cx={node.coordinates.x}
              cy={node.coordinates.y}
              r={6}
              fill={getNodeColor(node.status)}
              stroke="#0f172a"
              strokeWidth="2"
            />

            <text
              x={node.coordinates.x}
              y={node.coordinates.y + 16}
              textAnchor="middle"
              fill="#94a3b8"
              fontSize="10"
              fontWeight={selectedNodeId === node.id ? "bold" : "normal"}
              className="pointer-events-none select-none"
            >
              {node.name}
            </text>
          </g>
        ))}
      </svg>

      {/* Legend */}
      <div className="absolute bottom-4 right-4 flex gap-4 text-xs text-slate-400 bg-slate-800/90 p-2 rounded border border-slate-700">
        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-emerald-500"></div> Optimal</div>
        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-amber-500"></div> Warning</div>
        <div className="flex items-center gap-1"><div className="w-2 h-2 rounded-full bg-red-500"></div> Critical</div>
      </div>
    </div>
  );
};

