export const runSimulationAnalysis = async (params: SimulationParams): Promise<SimulationResult> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found. Returning mock simulation data.");
    return new Promise(resolve => setTimeout(() => resolve(MOCK_RESULT), 1500));
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      Act as a Digital Twin Simulation Engine for the Solar Supply Chain.
      Analyze the impact of the following variables:
      - Polysilicon Price Change: ${params.polysiliconPriceChange}%
      - Logistics Disruption (Port/Route): ${params.logisticDisruption ? 'YES (Major delays)' : 'NO'}
      - Demand Surge: ${params.demandSurge}%
      - New Tariffs: ${params.tariffImposition ? 'YES' : 'NO'}
      - Extreme Weather Event: ${params.weatherEvent ? 'YES' : 'NO'}

      Provide a structured JSON output containing:
      1. A short narrative describing the propagation of these shocks through the nodes (Raw Materials -> Manufacturing -> Logistics -> Installation).
      2. Quantitative impact estimates on KPIs (Landed Cost, OTIF, Carbon).
      3. Strategic recommendations for mitigation.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            narrative: { type: Type.STRING },
            kpiImpact: {
              type: Type.OBJECT,
              properties: {
                landedCostChange: { type: Type.NUMBER, description: "Percentage change in landed cost" },
                otifChange: { type: Type.NUMBER, description: "Percentage point change in On-Time-In-Full" },
                carbonFootprintChange: { type: Type.NUMBER, description: "Percentage change in emissions" },
                inventoryRisk: { type: Type.STRING, enum: ["Low", "Medium", "High"] }
              }
            },
            recommendations: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as SimulationResult;
    }

    throw new Error("Empty response from AI");

  } catch (error) {
    console.error("Simulation failed:", error);
    return MOCK_RESULT;
  }
};

