  const handleRunSimulation = async (params: SimulationParams) => {
    setIsSimulating(true);
    setSimulationResult(null);

    // Visual effect: Set nodes to random status to simulate "Processing" or "Impact"
    const tempNodes = nodes.map(n => ({
        ...n,
        status: Math.random() > 0.7 ? NodeStatus.WARNING : NodeStatus.OPTIMAL
    }));
    setNodes(tempNodes);

    try {
      const result = await runSimulationAnalysis(params);
      setSimulationResult(result);

      // Update KPIs based on simulation result
      const newKpis = [...kpis];
      newKpis[0] = { ...newKpis[0], trend: result.kpiImpact.otifChange, status: result.kpiImpact.otifChange >= 0 ? 'positive' : 'negative' };
      newKpis[1] = { ...newKpis[1], trend: result.kpiImpact.landedCostChange, status: result.kpiImpact.landedCostChange <= 0 ? 'positive' : 'negative' };
      newKpis[3] = { ...newKpis[3], trend: result.kpiImpact.carbonFootprintChange, status: result.kpiImpact.carbonFootprintChange <= 0 ? 'positive' : 'negative' };
      setKpis(newKpis);

      // Reset specific node statuses based on narrative hints (simple logic for demo)
      const severity = result.kpiImpact.inventoryRisk;
      const finalNodes = nodes.map(n => {
        if (severity === 'High' && (n.type === NodeType.MANUFACTURING || n.type === NodeType.LOGISTICS)) {
            return { ...n, status: NodeStatus.CRITICAL };
        }
        if (severity === 'Medium' && n.type === NodeType.LOGISTICS) {
            return { ...n, status: NodeStatus.WARNING };
        }
        return { ...n, status: NodeStatus.OPTIMAL };
      });
      setNodes(finalNodes);

    } catch (e) {
      console.error(e);
    } finally {
      setIsSimulating(false);
    }
  };

