export default App;

export enum NodeType {
  RAW_MATERIAL = 'RAW_MATERIAL',
  MANUFACTURING = 'MANUFACTURING',
  LOGISTICS = 'LOGISTICS',
  DISTRIBUTION = 'DISTRIBUTION',
  INSTALLATION = 'INSTALLATION'
}

export enum NodeStatus {
  OPTIMAL = 'OPTIMAL',
  WARNING = 'WARNING',
  CRITICAL = 'CRITICAL',
  OFFLINE = 'OFFLINE'
}

export interface SupplyNode {
  id: string;
  name: string;
  type: NodeType;
  status: NodeStatus;
  location: string;
  inventoryLevel: number; // 0-100%
  capacityUtilization: number; // 0-100%
  leadTimeDays: number;
  coordinates: { x: number; y: number };
}

export interface SimulationParams {
  // Commodities
  polysiliconPriceChange: number; // Percentage
  silverPriceChange: number; // Percentage
  aluminumPriceChange: number; // Percentage

  // Manufacturing & Ops
  yieldRateDegradation: number; // Percentage point drop
  energyCostChange: number; // Percentage

  // Logistics
  logisticDisruption: boolean;
  freightCostIndex: number; // 0-200, 100 is baseline

  // Market & Policy
  demandSurge: number; // Percentage
  tariffImposition: boolean;
  subsidyLevel: number; // Percentage
  interestRateChange: number; // Basis points

  // Risks
  weatherEvent: boolean;
  geopoliticalTension: boolean;
}

export interface SimulationResult {
  narrative: string;
  kpiImpact: {
    landedCostChange: number;
    otifChange: number;
    carbonFootprintChange: number;
    inventoryRisk: 'Low' | 'Medium' | 'High';
  };
  recommendations: string[];
}

export interface KPI {
  label: string;
  value: string;
  unit: string;
  trend: number; // percentage change
  status: 'positive' | 'negative' | 'neutral';
}

import { GoogleGenAI, Type } from "@google/genai";
import { SimulationParams, SimulationResult } from "../types";

// Mock result for fallback if no API key is present or error occurs
const MOCK_RESULT: SimulationResult = {
  narrative: "Simulation completed using fallback logic. The complex interaction of rising silver prices and logistics bottlenecks has created a bullwhip effect. While module assembly is resilient, the cost basis has shifted significantly, threatening project IRRs in the EU region.",
  kpiImpact: {
    landedCostChange: 12.4,
    otifChange: -15.2,
    carbonFootprintChange: 4.1,
    inventoryRisk: 'High'
  },
  recommendations: [
    "Hedge silver exposure immediately for Q3 contracts.",
    "Prioritize rail freight for European distribution to bypass port congestion.",
    "Renegotiate delivery timelines with Tier 1 EPCs."
  ]
};

export const runSimulationAnalysis = async (params: SimulationParams): Promise<SimulationResult> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found. Returning mock simulation data.");
    return new Promise(resolve => setTimeout(() => resolve(MOCK_RESULT), 1500));
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      Act as a Digital Twin Simulation Engine for the Solar Supply Chain.
      Analyze the impact of the following variables on the global supply chain (China -> SE Asia -> Global Markets):

      1. COMMODITIES
      - Polysilicon Price Change: ${params.polysiliconPriceChange}%
      - Silver Price Change: ${params.silverPriceChange}% (Impacts Cell Metallization cost)
      - Aluminum Price Change: ${params.aluminumPriceChange}% (Impacts Module Frames)

      2. MANUFACTURING & OPS
      - Yield Rate Degradation: ${params.yieldRateDegradation}% (Higher scrap rates)
      - Energy Cost Change: ${params.energyCostChange}% (Impacts Poly/Wafer/Glass production)

      3. LOGISTICS
      - Major Disruption: ${params.logisticDisruption ? 'YES (Port Closures)' : 'NO'}
      - Freight Cost Index: ${params.freightCostIndex} (Baseline 100)

      4. MARKET & POLICY
      - Demand Surge: ${params.demandSurge}%
      - Tariffs: ${params.tariffImposition ? 'YES' : 'NO'}
      - Subsidy Level: ${params.subsidyLevel}%
      - Interest Rate Change: ${params.interestRateChange} bps

      5. RISKS
      - Extreme Weather: ${params.weatherEvent ? 'YES' : 'NO'}
      - Geopolitical Tension: ${params.geopoliticalTension ? 'YES' : 'NO'}

      Provide a structured JSON output containing:
      1. A detailed narrative describing the propagation of these shocks. Focus on bottlenecks and financial implications.
      2. Quantitative impact estimates on KPIs.
      3. Strategic recommendations for mitigation.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            narrative: { type: Type.STRING },
            kpiImpact: {
              type: Type.OBJECT,
              properties: {
                landedCostChange: { type: Type.NUMBER, description: "Percentage change in landed cost" },
                otifChange: { type: Type.NUMBER, description: "Percentage point change in On-Time-In-Full" },
                carbonFootprintChange: { type: Type.NUMBER, description: "Percentage change in emissions" },
                inventoryRisk: { type: Type.STRING, enum: ["Low", "Medium", "High"] }
              }
            },
            recommendations: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as SimulationResult;
    }

    throw new Error("Empty response from AI");

  } catch (error) {
    console.error("Simulation failed:", error);
    return MOCK_RESULT;
  }
};

