type ViewState = 'DASHBOARD' | 'ANALYTICS' | 'SETTINGS';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>('DASHBOARD');
  const [nodes, setNodes] = useState<SupplyNode[]>(INITIAL_NODES);
  const [selectedNode, setSelectedNode] = useState<SupplyNode | null>(null);
  const [kpis, setKpis] = useState<KPI[]>(INITIAL_KPIS);
  const [isSimulating, setIsSimulating] = useState(false);
  const [simulationResult, setSimulationResult] = useState<SimulationResult | null>(null);

  const handleRunSimulation = async (params: SimulationParams) => {
    setIsSimulating(true);
    setSimulationResult(null);

    // Visual effect: Set nodes to random status to simulate "Processing" or "Impact"
    const tempNodes = nodes.map(n => ({
        ...n,
        status: Math.random() > 0.7 ? NodeStatus.WARNING : NodeStatus.OPTIMAL
    }));
    setNodes(tempNodes);

    try {
      const result = await runSimulationAnalysis(params);
      setSimulationResult(result);

      // Update KPIs based on simulation result
      const newKpis = [...kpis];

      // 1. OTIF (Additive Change)
      // High OTIF is GOOD. Increase (positive change) is positive status.
      const currentOtif = parseFloat(newKpis[0].value);
      const otifChange = result.kpiImpact.otifChange;
      const newOtif = Math.min(100, Math.max(0, currentOtif + otifChange)).toFixed(1);
      newKpis[0] = { 
        ...newKpis[0], 
        value: newOtif,
        trend: otifChange, 
        status: otifChange >= 0 ? 'positive' : 'negative' 
      };

      // 2. Landed Cost (Multiplicative Change)
      // Low Cost is GOOD. Increase (positive change) is negative status.
      const currentCost = parseFloat(newKpis[1].value);
      const costChange = result.kpiImpact.landedCostChange;
      const newCost = (currentCost * (1 + costChange / 100)).toFixed(3);
      newKpis[1] = { 
        ...newKpis[1], 
        value: newCost,
        trend: costChange, 
        status: costChange <= 0 ? 'positive' : 'negative' 
      };

      // 3. Lead Time (Proxy logic since simulation doesn't strictly return this yet)
      // Let's assume logistics disruption adds time
      let leadTimeImpact = 0;
      if (params.logisticDisruption) leadTimeImpact += 15;
      if (params.weatherEvent) leadTimeImpact += 5;
      const currentLead = 42;
      const newLead = currentLead + leadTimeImpact;
      newKpis[2] = {
        ...newKpis[2],
        value: newLead.toString(),
        trend: leadTimeImpact > 0 ? leadTimeImpact : 0,
        status: leadTimeImpact === 0 ? 'neutral' : 'negative'
      };

      // 4. Carbon (Multiplicative Change)
      // Low Carbon is GOOD. Increase (positive change) is negative status.
      const currentCarbon = parseFloat(newKpis[3].value);
      const carbonChange = result.kpiImpact.carbonFootprintChange;
      const newCarbon = (currentCarbon * (1 + carbonChange / 100)).toFixed(0);
      newKpis[3] = { 
        ...newKpis[3], 
        value: newCarbon,
        trend: carbonChange, 
        status: carbonChange <= 0 ? 'positive' : 'negative' 
      };

      setKpis(newKpis);

      // Reset specific node statuses based on narrative hints
      const severity = result.kpiImpact.inventoryRisk;
      const finalNodes = nodes.map(n => {
        if (severity === 'High' && (n.type === NodeType.MANUFACTURING || n.type === NodeType.LOGISTICS)) {
            return { ...n, status: NodeStatus.CRITICAL };
        }
        if (severity === 'Medium' && n.type === NodeType.LOGISTICS) {
            return { ...n, status: NodeStatus.WARNING };
        }
        // Specific checks for user params to highlight nodes
        if (params.logisticDisruption && n.type === NodeType.LOGISTICS) {
            return { ...n, status: NodeStatus.CRITICAL };
        }
        if (params.weatherEvent && n.location === 'Spain') {
             return { ...n, status: NodeStatus.WARNING };
        }

        return { ...n, status: NodeStatus.OPTIMAL };
      });
      setNodes(finalNodes);

    } catch (e) {
      console.error(e);
    } finally {
      setIsSimulating(false);
    }
  };

  const NavButton = ({ view, label }: { view: ViewState, label: string }) => (
    <button 
      onClick={() => setCurrentView(view)}
      className={`transition-colors ${currentView === view ? 'text-white border-b-2 border-blue-500 pb-4 -mb-4' : 'hover:text-white text-slate-400'}`}
