              </svg>
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight text-white">SolarChain<span className="text-blue-400 font-light">Twin</span></h1>
              <div className="text-[10px] text-emerald-500 font-mono tracking-wider flex items-center gap-1">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></span>
                SYSTEM ONLINE
              </div>
            </div>
          </div>
          <div className="flex gap-6 text-sm font-medium">
            <NavButton view="DASHBOARD" label="Dashboard" />
            <NavButton view="ANALYTICS" label="Analytics" />
            <NavButton view="SETTINGS" label="Settings" />
          </div>
          <div className="flex items-center gap-3">
             <div className="text-right hidden md:block">
                <div className="text-xs text-slate-400">Current User</div>
                <div className="text-sm font-semibold text-white">Arch. Sarah Connor</div>
             </div>
             <div className="h-8 w-8 rounded-full bg-slate-700 border border-slate-600"></div>
          </div>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="flex-grow max-w-[1920px] mx-auto p-6 w-full">

        {currentView === 'DASHBOARD' && (
          <div className="grid grid-cols-12 gap-6 h-[calc(100vh-140px)]">
            {/* KPI Row - Top */}
            <div className="col-span-12 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 shrink-0 h-min">
              {kpis.map((kpi, idx) => <KPICard key={idx} kpi={kpi} />)}
            </div>

            {/* Middle Section (Map + Charts) - Flexible Height */}
            <div className="col-span-12 lg:col-span-8 flex flex-col gap-6 h-full min-h-0">
              <NetworkMap 
                nodes={nodes} 
                selectedNodeId={selectedNode?.id || null} 
                onNodeSelect={setSelectedNode} 
              />
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 h-[300px] shrink-0">
                <div className="bg-slate-800 rounded-xl border border-slate-700 p-6 shadow-xl">
                  <CostTrendChart />
                </div>
                <div className="bg-slate-800 rounded-xl border border-slate-700 p-6 shadow-xl">
                  <InventoryChart />
                </div>
              </div>
            </div>

            {/* Right Column (Simulation Panel) - Scrollable if needed */}
            <div className="col-span-12 lg:col-span-4 flex flex-col gap-6 h-full min-h-0 overflow-y-auto custom-scrollbar">
              {selectedNode && (
                <div className="bg-slate-800 rounded-xl border border-slate-700 p-6 animate-fadeIn shrink-0">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <h3 className="text-lg font-bold text-white">{selectedNode.name}</h3>
                      <p className="text-sm text-slate-400">{selectedNode.location} • {selectedNode.type}</p>
                    </div>
                    <span className={`px-2 py-1 rounded text-xs font-bold uppercase ${
                      selectedNode.status === NodeStatus.OPTIMAL ? 'bg-emerald-500/20 text-emerald-400' :
                      selectedNode.status === NodeStatus.WARNING ? 'bg-amber-500/20 text-amber-400' :
                      'bg-red-500/20 text-red-400'
                    }`}>
                      {selectedNode.status}
                    </span>
                  </div>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div className="p-3 bg-slate-900 rounded border border-slate-700">
                      <div className="text-slate-500 mb-1">Inventory</div>
                      <div className="text-white font-mono text-lg">{selectedNode.inventoryLevel}%</div>
                      <div className="w-full bg-slate-700 h-1.5 rounded-full mt-2">
                        <div className="bg-blue-500 h-1.5 rounded-full" style={{ width: `${selectedNode.inventoryLevel}%` }}></div>
                      </div>
                    </div>
                    <div className="p-3 bg-slate-900 rounded border border-slate-700">
                      <div className="text-slate-500 mb-1">Utilization</div>
                      <div className="text-white font-mono text-lg">{selectedNode.capacityUtilization}%</div>
                      <div className="w-full bg-slate-700 h-1.5 rounded-full mt-2">
                        <div className="bg-purple-500 h-1.5 rounded-full" style={{ width: `${selectedNode.capacityUtilization}%` }}></div>
                      </div>
                    </div>
                  </div>
                  <button 
                    onClick={() => setSelectedNode(null)}
                    className="mt-4 w-full py-2 text-sm text-slate-400 hover:text-white border border-slate-700 rounded hover:bg-slate-700 transition"
                  >
                    Close Details
                  </button>
                </div>
              )}

              <SimulationPanel onRunSimulation={handleRunSimulation} isSimulating={isSimulating} />

              {simulationResult && (
                <div className="bg-slate-800 rounded-xl border border-blue-500/30 p-6 shadow-2xl shadow-blue-900/10 animate-slideUp shrink-0">
                    <div className="flex items-center gap-2 mb-3">
                      <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></div>
                      <h3 className="font-bold text-white uppercase tracking-wide text-sm">Simulation Output</h3>
                    </div>

                    <div className="prose prose-invert prose-sm max-w-none mb-4">
                      <p className="text-slate-300 leading-relaxed text-xs">
                        {simulationResult.narrative}
                      </p>
                    </div>

                    <div className="space-y-2">
                      <h4 className="text-xs font-bold text-slate-500 uppercase">Strategic Recommendations</h4>
                      {simulationResult.recommendations.map((rec, i) => (
                        <div key={i} className="flex items-start gap-2 text-xs text-emerald-400 bg-emerald-500/10 p-2 rounded border border-emerald-500/20">
                          <svg className="w-4 h-4 flex-shrink-0 mt-0.5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                          </svg>
                          {rec}
                        </div>
                      ))}
                    </div>
                </div>
              )}
            </div>
          </div>
        )}

        {currentView === 'ANALYTICS' && <AnalyticsView />}
        {currentView === 'SETTINGS' && <SettingsView />}

      </main>
    </div>
  );
}

export default App;
